<template><section class="af-diagnostics"><div class="af-diagnostics__title"><strong>诊断</strong><el-tag size="small" :type="errors?'danger':warnings?'warning':'success'">{{ errors }} 错误 / {{ warnings }} 警告</el-tag></div><div class="af-diagnostics__list"><button v-for="item in diagnostics" :key="`${item.code}:${item.nodeId||item.edgeId||item.propertyPath}`" type="button" :class="`is-${item.severity}`" @click="$emit('locate',item)"><b>{{ item.code }}</b><span>{{ item.message }}</span><small>{{ item.propertyPath||item.nodeId||item.edgeId }}</small></button><small v-if="!diagnostics.length">当前流程没有诊断。</small></div></section></template>
<script setup lang="ts">import{computed}from'vue';import type{TwinActionFlowDiagnostic}from'../contracts/action-flow-v2';const props=defineProps<{diagnostics:TwinActionFlowDiagnostic[]}>();defineEmits<{(e:'locate',d:TwinActionFlowDiagnostic):void}>();const errors=computed(()=>props.diagnostics.filter(x=>x.severity==='error').length);const warnings=computed(()=>props.diagnostics.filter(x=>x.severity==='warning').length);</script>
<style scoped>.af-diagnostics{min-height:110px;border-top:1px solid var(--el-border-color);padding:8px 10px;background:var(--el-bg-color)}.af-diagnostics__title{display:flex;justify-content:space-between;align-items:center}.af-diagnostics__list{display:flex;gap:6px;overflow:auto;margin-top:6px}.af-diagnostics__list button{min-width:240px;max-width:360px;text-align:left;padding:6px;border:1px solid var(--el-border-color);border-radius:6px;background:var(--el-fill-color-blank)}.af-diagnostics__list button.is-error{border-color:var(--el-color-danger)}.af-diagnostics__list button.is-warning{border-color:var(--el-color-warning)}.af-diagnostics__list b,.af-diagnostics__list span,.af-diagnostics__list small{display:block}.af-diagnostics__list small{color:var(--el-text-color-secondary)}</style>
